def main():
    base=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    ids=[e["id"] for e in ENTRIES]; assert len(ids)==len(set(ids)), "duplicate ids"
    valid={s["id"] for t in SECTIONS.values() for s in t}
    for e in ENTRIES:
        for s in e["sections"]: assert s in valid, (e["id"],s)
    data=dict(generated=CHECKED, sections=SECTIONS, entries=ENTRIES, benchmarks=BENCH, people=PEOPLE, link_checks={})
    path=os.path.join(base,"data.json")
    if os.path.exists(path):
        data["link_checks"]=json.load(open(path)).get("link_checks",{})
    write(base,data)
    print(len(ENTRIES),"entries,",len(BENCH),"bench rows,",len(PEOPLE),"people")
def write(base,data):
    json.dump(data,open(os.path.join(base,"data.json"),"w"),ensure_ascii=False,indent=1)
    open(os.path.join(base,"data.js"),"w").write("// Generated by tools/build_data.py - edit that file (or data.json) and rebuild.\nwindow.DIRECTORY_DATA = "+json.dumps(data,ensure_ascii=False,indent=1)+";\n")
    from build_agent_files import build as build_agent_files  # JSON-LD in index.html + llms.txt
    build_agent_files(base,data)
if __name__=="__main__": main()
